// Open proposals: how named Telangana businesses could use AI calling and automation.
// Generated by scripts/proposals.py from a public homepage check of each business.
// These businesses are NOT clients; every page says so and offers correction or removal.
import data from "./proposals.json";

export type Proposal = {
  slug: string;
  name: string;
  city: string;
  industry: string;
  site: string;
  checked: string; // ISO date of the homepage check
  date: string; // ISO publish date; pages appear only once this date has passed
  facts: { label: string; ok: boolean }[];
  voice: string[];
  stack: string[];
  steps: string[];
};

// Frozen at the first batch (owner, 12 Nov 2026): these pages name real businesses, so they stay
// reachable by link for sales but are noindex and out of the sitemap. No new weekly batches.
export const PROPOSALS: Proposal[] = (data as Proposal[]).filter((p) => p.date <= "2026-11-10");

export const getProposal = (slug: string) => PROPOSALS.find((p) => p.slug === slug);

export const proposalIndustries = () => [...new Set(PROPOSALS.map((p) => p.industry))].sort();
